function uploadImages() {
  if(slideInterval) clearInterval(slideInterval);
  if (loadedImages.length === 0) return;

  if (loadedImages.length === 1) {
    sendFrame(loadedImages[0]);
    document.getElementById('slideStatus').innerText = "Отображается 1 фото";
  } else {
    let idx = 0;
    sendFrame(loadedImages[idx]);
    document.getElementById('slideStatus').innerText = "Слайд-шоу запущено (3 сек)";
    slideInterval = setInterval(() => {
      idx = (idx + 1) % loadedImages.length;
      sendFrame(loadedImages[idx]);
    }, 3000);
  }
}

function playVideo() {
  if(slideInterval) clearInterval(slideInterval);
  let file = document.getElementById('videoInput').files[0];
  if(!file) return alert('Выберите видео!');

  let video = document.createElement('video');
  video.src = URL.createObjectURL(file);
  video.play();

  let canvas = document.createElement('canvas');
  canvas.width = 128; canvas.height = 64;
  let ctx = canvas.getContext('2d');

  video.ontimeupdate = () => {
    ctx.drawImage(video, 0, 0, 128, 64);
    let imgData = ctx.getImageData(0, 0, 128, 64);
    let d = imgData.data;
    for (let i = 0; i < d.length; i += 4) {
      let v = (0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2]) >= 128 ? 255 : 0;
      d[i] = d[i+1] = d[i+2] = v;
    }
    ctx.putImageData(imgData, 0, 0);
    fetch('/frame', { method: 'POST', body: convertCanvasToBytes(ctx) }).catch(()=>{});
  };
  document.getElementById('videoStatus').innerText = "Стриминг видео...";
}
