void handleFrame() {
  if (server.hasArg("plain")) {
    String body = server.arg("plain");
    if (body.length() == 1024) {
      display.clearDisplay();
      display.drawBitmap(0, 0, (const uint8_t*)body.c_str(), 128, 64, WHITE, BLACK);
      display.display();
    }
  }
  server.send(200, "text/plain", "OK");
}

void setup() {
  Wire.begin(21, 22);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);

  WiFi.softAP("MicroPhone-ESP32", "12345678");

  server.on("/", []() { server.send(200, "text/html", HTML_PAGE); });
  server.on("/frame", HTTP_POST, handleFrame);
  server.begin();

  display.clearDisplay();
  display.setTextColor(WHITE);
  display.setCursor(0, 0);
  display.println("WiFi: MicroPhone-ESP32");
  display.println("Pass: 12345678");
  display.println("");
  display.println("Browser IP:");
  display.println("192.168.4.1");
  display.display();
}

void loop() {
  server.handleClient();
}
